'use client'

import * as React from 'react'
import { ContextMenu as ContextPrimitive } from 'radix-ui'
import { NavArrowRight } from 'iconoir-react'
import { cn } from '@/lib/utils'
import { MenuItemContent, menuItemClass, menuSurfaceClass, type MenuItemContentProps } from '@/registry/satin/ui/dropdown'
import { trackPointerModality } from '@/registry/satin/ui/pointer-modality'

// Rings after a mouse press: see pointer-modality.tsx.
trackPointerModality()

/**
 * ContextMenu, 1:1 with the uiKit design (🆕 context menu & hover card): DropdownMenu's surface
 * and rows, opened by right-click (or a long press) on its target, at the pointer. 255 wide, 4px
 * in, rows 0 apart, separators a 1px bg/muted rule. Shortcuts on the right as Kbd; a submenu row
 * ends in a text/muted chevron (the kit's `showSubmenu`) and opens beside it, 4px off; destructive
 * rows are action/destructive/fg (red-400 in dark), icon included, and go last.
 *
 * Built on the Radix ContextMenu: arrow keys, typeahead, Escape, Shift+F10 / the menu key on the
 * focused target.
 *
 * Other props, `ref` included, go to the menu's panel (the Radix Content).
 */
export interface ContextMenuProps
  extends Omit<React.ComponentProps<typeof ContextPrimitive.Content>, 'children' | 'asChild' | 'onFocusOutside'> {
  /** What right-click opens the menu on. Rendered with `asChild`, so pass one element. */
  trigger: React.ReactNode
  /** `ContextMenuItem`s, `ContextMenuSub`s and `ContextMenuSeparator`s. */
  children: React.ReactNode
  onOpenChange?: (open: boolean) => void
  /** Portal target. Defaults to `document.body`. */
  container?: HTMLElement | null
  /** Modal menus block the rest of the page while open. */
  modal?: boolean
  /** Focus moved outside a non-modal menu; call `preventDefault()` to keep it open. */
  onFocusOutside?: (event: Event) => void
  className?: string
}

const contentClass = cn(
  'sa:pointer-events-auto sa:z-50 sa:flex sa:w-[255px] sa:max-w-[calc(100vw-16px)] sa:flex-col sa:overflow-x-clip sa:overflow-y-auto sa:p-1',
  menuSurfaceClass,
  'sa:outline-none sa:data-[state=open]:animate-[satin-enter_var(--sa-duration-base)_var(--sa-ease-out)]',
)

export function ContextMenu({
  trigger,
  children,
  onOpenChange,
  container,
  modal = true,
  onFocusOutside,
  className,
  ...props
}: ContextMenuProps) {
  return (
    <ContextPrimitive.Root onOpenChange={onOpenChange} modal={modal}>
      <ContextPrimitive.Trigger asChild>{trigger}</ContextPrimitive.Trigger>
      <ContextPrimitive.Portal container={container}>
        <ContextPrimitive.Content
          collisionPadding={8}
          {...props}
          data-slot="context-menu"
          onFocusOutside={onFocusOutside}
          className={cn(contentClass, 'sa:origin-(--radix-context-menu-content-transform-origin)', 'sa:max-h-(--radix-context-menu-content-available-height)', className)}
        >
          {children}
        </ContextPrimitive.Content>
      </ContextPrimitive.Portal>
    </ContextPrimitive.Root>
  )
}

export interface ContextMenuItemProps
  extends Omit<React.ComponentProps<typeof ContextPrimitive.Item>, 'children'>,
    Pick<MenuItemContentProps, 'icon' | 'shortcut' | 'description'> {
  label: string
  /** Deletes or removes: action/destructive/fg, and best placed last. */
  destructive?: boolean
}

export function ContextMenuItem({ label, icon, shortcut, description, destructive, className, ...props }: ContextMenuItemProps) {
  return (
    <ContextPrimitive.Item
      data-slot="context-menu-item"
      textValue={label}
      className={cn(menuItemClass, destructive && 'sa:[&_*]:text-action-destructive-fg', className)}
      {...props}
    >
      <MenuItemContent label={label} icon={icon} shortcut={shortcut} description={description} layout="inline" />
    </ContextPrimitive.Item>
  )
}

export interface ContextMenuSubProps
  extends Omit<React.ComponentProps<typeof ContextPrimitive.SubContent>, 'children' | 'asChild'>,
    Pick<MenuItemContentProps, 'icon'> {
  label: string
  /** The submenu's items. */
  children: React.ReactNode
  disabled?: boolean
}

/**
 * A row that opens a submenu beside it (hover, →, or Enter).
 *
 * Other props, `ref` and `className` included, go to the submenu's panel (the Radix SubContent),
 * not to the row.
 */
export function ContextMenuSub({ label, icon, children, disabled, className, ...props }: ContextMenuSubProps) {
  return (
    <ContextPrimitive.Sub>
      <ContextPrimitive.SubTrigger
        data-slot="context-menu-sub"
        disabled={disabled}
        textValue={label}
        className={cn(menuItemClass, 'sa:data-[state=open]:bg-bg-selected')}
      >
        <MenuItemContent label={label} icon={icon} layout="inline" />
        <NavArrowRight aria-hidden className="sa:size-4 sa:text-text-muted sa:[stroke-width:1.875] sa:rtl:-scale-x-100" />
      </ContextPrimitive.SubTrigger>
      <ContextPrimitive.Portal>
        <ContextPrimitive.SubContent
          sideOffset={4}
          alignOffset={-5}
          collisionPadding={8}
          {...props}
          className={cn(contentClass, 'sa:w-[220px] sa:origin-(--radix-context-menu-content-transform-origin)', className)}
        >
          {children}
        </ContextPrimitive.SubContent>
      </ContextPrimitive.Portal>
    </ContextPrimitive.Sub>
  )
}

/** A 1px bg/muted rule between groups of rows. */
export function ContextMenuSeparator({ className }: { className?: string }) {
  return <ContextPrimitive.Separator className={cn('sa:-mx-1 sa:my-1 sa:h-px sa:bg-bg-muted', className)} />
}
